        "Dobbel oktav <span class=\"name-en\">(Double octave)</span>": "Double octave",
        "dobbel oktav, 24 halvtoner": "double octave, 24 semitones",
        "13 halvtoner, også kalt oktav + liten sekund": "13 semitones, also called octave + minor 2nd",
        "14 halvtoner, også kalt oktav + stor sekund": "14 semitones, also called octave + major 2nd",
