        "{navn}, der den øverste tonen var {c} for høy.": "{navn}, where the top note was {c} too high.",
        "{navn}, der den øverste tonen var {c} for lav.": "{navn}, where the top note was {c} too low.",
        "Retningen var riktig, men forskjellen var {c}, ikke {d}.": "The direction was right, but the difference was {c}, not {d}.",
