        "<a class=\"btn\" href=\"quiz-rytme.html?type=hor\">Gehørquiz: rytme</a> <a class=\"btn\" href=\"quiz-rytme.html?type=les\">Teoriquiz: rytme</a>": "<a class=\"btn\" href=\"quiz-rytme.html?type=hor\">Ear quiz: rhythm</a> <a class=\"btn\" href=\"quiz-rytme.html?type=les\">Theory quiz: rhythm</a>",
